def calculate_percentage_change():
    total_amount = 0
    prev_month_amount = 0
    for row in reader:
        total_amount += float(row[1])
        if row[0] == '2025-02':
            prev_month_amount = total_amount
    percentage_change = ((total_amount - prev_month_amount) / prev_month_amount) * 100
    return round(percentage_change, 2)

